mapper.insert:
INSERT INTO REFUNDS (
    ORDER_ID, USER_ID, AMOUNT, REASON, STATUS
) VALUES (
    #{orderId}, #{userId}, #{amount}, #{reason}, #{status}
)

mapper.select:
SELECT R.REFUND_ID, R.ORDER_ID, O.ORDER_CODE, R.USER_ID, U.NICKNAME AS USER_NICKNAME, R.AMOUNT, R.REASON, R.STATUS, R.ADMIN_USER_ID, A.NICKNAME AS ADMIN_NICKNAME, R.ADMIN_NOTE, R.REQUESTED_AT, R.PROCESSED_AT, R.COMPLETED_AT FROM REFUNDS R JOIN ORDERS O ON O.ORDER_ID = R.ORDER_ID LEFT JOIN USERS U ON U.USER_ID = R.USER_ID LEFT JOIN USERS A ON A.USER_ID = R.ADMIN_USER_ID
R.STATUS = #{status}
ORDER BY R.REQUESTED_AT DESC LIMIT #{limit} OFFSET #{offset}
